#!/usr/bin/env python3\n\"\"\"\nTest Human-in-the-Loop Incident Workflow\n\nThis script demonstrates the complete incident lifecycle:\n1. OPEN -> AI Analysis -> INVESTIGATING\n2. Human Review -> Execute Remediation -> MITIGATED\n3. Auto-Resolution -> RESOLVED\n\"\"\"\n\nimport requests\nimport time\nimport json\nfrom datetime import datetime\n\nBASE_URL = \"http://localhost:8000\"\n\ndef test_incident_workflow():\n    print(\"🚀 Testing Human-in-the-Loop Incident Workflow\")\n    print(\"=\" * 50)\n    \n    # Step 1: Create incident via webhook\n    print(\"\\n1️⃣ Creating incident via webhook...\")\n    webhook_data = {\n        \"title\": \"Critical Payment Gateway Failure\",\n        \"message\": \"Payment processing completely down. 100% error rate on all payment attempts. Revenue impact: $5,000/minute\",\n        \"severity\": \"critical\",\n        \"source\": \"datadog\"\n    }\n    \n    try:\n        response = requests.post(\n            f\"{BASE_URL}/api/v1/ingest/webhook/generic\",\n            json=webhook_data,\n            headers={\"X-API-Key\": \"nexus_YaTvj5MmL-U6Mz_Qml0BfDDqnygNXbo0-OALx_arOdE\"}\n        )\n        \n        if response.status_code == 202:\n            incident_data = response.json()\n            incident_id = incident_data[\"incident_id\"]\n            print(f\"✅ Incident created: {incident_id}\")\n            print(f\"   Status: OPEN -> AI Analysis -> INVESTIGATING\")\n        else:\n            print(f\"❌ Failed to create incident: {response.status_code}\")\n            return\n            \n    except requests.exceptions.ConnectionError:\n        print(\"❌ Backend not running. Please start the backend server.\")\n        return\n    \n    # Step 2: Wait for AI analysis (6 seconds)\n    print(\"\\n2️⃣ Waiting for AI analysis to complete...\")\n    time.sleep(8)\n    \n    # Step 3: Get incident details\n    print(\"\\n3️⃣ Fetching incident details...\")\n    try:\n        response = requests.get(f\"{BASE_URL}/api/v1/incidents/{incident_id}\")\n        if response.status_code == 200:\n            incident = response.json()\n            print(f\"✅ Incident Status: {incident.get('status', 'Unknown')}\")\n            print(f\"   AI Confidence: {incident.get('ai_confidence', 0) * 100:.1f}%\")\n            print(f\"   Root Cause: {incident.get('ai_summary', 'Analysis pending...')[:100]}...\")\n        else:\n            print(f\"❌ Failed to fetch incident: {response.status_code}\")\n    except Exception as e:\n        print(f\"❌ Error fetching incident: {e}\")\n    \n    # Step 4: Human reviews and approves remediation\n    print(\"\\n4️⃣ Human operator reviews AI analysis and approves remediation...\")\n    print(\"   👤 Human Decision: 'AI analysis looks correct, approve automated remediation'\")\n    \n    try:\n        response = requests.post(f\"{BASE_URL}/api/v1/incidents/{incident_id}/execute-remediation\")\n        if response.status_code == 200:\n            result = response.json()\n            print(f\"✅ Remediation Started: {result.get('message', 'Success')}\")\n            print(f\"   Status: INVESTIGATING -> MITIGATED\")\n            print(f\"   Human Context: {result.get('human_context', 'N/A')}\")\n        else:\n            print(f\"❌ Failed to execute remediation: {response.status_code}\")\n    except Exception as e:\n        print(f\"❌ Error executing remediation: {e}\")\n    \n    # Step 5: Wait for auto-resolution\n    print(\"\\n5️⃣ Waiting for automated resolution (30 seconds)...\")\n    print(\"   🤖 Automated remediation pipeline executing...\")\n    \n    for i in range(6):\n        time.sleep(5)\n        print(f\"   ⏳ Progress: {(i+1)*5}/30 seconds\")\n    \n    # Step 6: Verify final resolution\n    print(\"\\n6️⃣ Verifying incident resolution...\")\n    try:\n        response = requests.get(f\"{BASE_URL}/api/v1/incidents/{incident_id}\")\n        if response.status_code == 200:\n            incident = response.json()\n            final_status = incident.get('status', 'Unknown')\n            print(f\"✅ Final Status: {final_status}\")\n            \n            if final_status == 'RESOLVED':\n                print(f\"   Resolution Method: {incident.get('resolution_method', 'Automated')}\")\n                print(f\"   Resolution Summary: {incident.get('resolution_summary', 'N/A')}\")\n                print(f\"   Human Approved: {incident.get('human_approved', False)}\")\n                print(f\"   Impact Scope: {incident.get('impact_scope', 'N/A')}\")\n            else:\n                print(f\"   ⚠️  Incident not yet resolved. Current status: {final_status}\")\n        else:\n            print(f\"❌ Failed to fetch final incident state: {response.status_code}\")\n    except Exception as e:\n        print(f\"❌ Error fetching final state: {e}\")\n    \n    print(\"\\n\" + \"=\" * 50)\n    print(\"🎉 Human-in-the-Loop Workflow Test Complete!\")\n    print(\"\\n📊 Workflow Summary:\")\n    print(\"   1. OPEN (Incident Created)\")\n    print(\"   2. INVESTIGATING (AI Analysis Complete)\")\n    print(\"   3. MITIGATED (Human-Approved Remediation)\")\n    print(\"   4. RESOLVED (Automated Resolution)\")\n    print(\"\\n💡 Key Features Demonstrated:\")\n    print(\"   ✅ 6-second AI root cause analysis\")\n    print(\"   ✅ Human oversight and approval\")\n    print(\"   ✅ Automated remediation execution\")\n    print(\"   ✅ Impact scope and business context\")\n    print(\"   ✅ Complete audit trail\")\n\nif __name__ == \"__main__\":\n    test_incident_workflow()\n